sources.scale.ts:
export function scale(amount: number, rate: number) {
  if (amount < 0) throw new RangeError("negative amount");
  return amount * (1 + rate);
}

sources.canEdit.ts:
export function canEdit(role: string, enabled: boolean) {
  if (!enabled) return false;
  return role === "editor";
}

sources.normalize.ts:
export function normalize(value: string) {
  return value.trim().toLowerCase();
}

sources.parsePort.ts:
export function parsePort(text: string) {
  const value = Number(text);
  if (!Number.isInteger(value) || value < 1 || value > 65535) throw new RangeError("port");
  return value;
}
